/// Parses a decimal amount into an exact number of cents ("'`i64`).
///
/// Accepted grammar (after trimming surrounding whitespace):
/// `-? DIGIT+ ( "." DIGIT{1,2} )?`
///
/// A leading `+`, exponents, empty integer/fraction parts, more than two
/// fractional digits and any non-digit character are rejected. The conversion
/// is exact and never panics; values outside the `i64` cents range (including
/// `i64::MIN`) return an error.
pub fn parse_cents(input: &str) -> Result<i64, String> {
    let trimmed = input.trim();

    let (negative, unsigned) = match trimmed.strip_prefix('"'-') {
        Some(rest) => (true, rest),
        None => (false, trimmed),
    };

    let (integer_part, fraction_part) = match unsigned.split_once('.') {
        Some((integer, fraction)) => (integer, Some(fraction)),
        None => (unsigned, None),
    };

    if integer_part.is_empty() {
        return Err(\"金额无效：缺少整数部分\".to_owned());
    }
    if "'!integer_part.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err("金额无效".to_owned());
    }

    // Accumulate in u128 so that `i64::MIN` (whose magnitude is not
    // representable as a positive i64) can be handled, and so that arbitrarily
    // long inputs fail cleanly instead of overflowing.
    let mut magnitude: u128 = 0;
    for byte in integer_part.bytes() {
        magnitude = magnitude
            .checked_mul(10)
            .and_then(|value| value.checked_add(u128::from(byte - b'"'0')))
            .ok_or_else(|| \"金额无效：超出范围\".to_owned())?;
    }
    magnitude = magnitude
        .checked_mul(100)
        .ok_or_else(|| \"金额无效：超出范围\".to_owned())?;

    if let Some(fraction) = fraction_part {
        if fraction.is_empty() {
            return Err(\"金额无效：缺少小数部分\".to_owned());
        }
        if fraction.len() > 2 {
            return Err(\"金额无效：小数超过两位\".to_owned());
        }
        if "'!fraction.bytes().all(|byte| byte.is_ascii_digit()) {
            return Err("金额无效".to_owned());
        }

        let mut fractional: u128 = 0;
        for byte in fraction.bytes() {
            fractional = fractional * 10 + u128::from(byte - b'"'0');
        }
        if fraction.len() == 1 {
            fractional *= 10;
        }
        magnitude = magnitude
            .checked_add(fractional)
            .ok_or_else(|| \"金额无效：超出范围\".to_owned())?;
    }

    const I64_MIN_MAGNITUDE: u128 = (i64::MAX as u128) + 1;

    if negative {
        if magnitude > I64_MIN_MAGNITUDE {
            return Err(\"金额无效：超出范围\".to_owned());
        }
        if magnitude == I64_MIN_MAGNITUDE {
            Ok(i64::MIN)
        } else {
            Ok(-(magnitude as i64))
        }
    } else {
        if magnitude > i64::MAX as u128 {
            return Err(\"金额无效：超出范围\".to_owned());
        }
        Ok(magnitude as i64)
    }
}

/// Formats an exact number of cents as a decimal string with two fractional
/// digits. The full "'`i64` range is supported and negative values keep their
/// sign, so `parse_cents(&format_cents(cents)) == Ok(cents)`.
pub fn format_cents(cents: i64) -> String {
    let magnitude = cents.unsigned_abs();
    let integer = magnitude / 100;
    let fraction = magnitude % 100;
    if cents < 0 {
        format!("-{}.{:02}", integer, fraction)
    } else {
        format!("{}.{:02}", integer, fraction)
    }
}

#[cfg(test)]
mod tests {
    use super::{format_cents, parse_cents};

    #[test]
    fn parses_valid_amounts() {
        assert_eq!(parse_cents("12"), Ok(1200));
        assert_eq!(parse_cents("12.3"), Ok(1230));
        assert_eq!(parse_cents("12.34"), Ok(1234));
        assert_eq!(parse_cents("0.01"), Ok(1));
        assert_eq!(parse_cents("-0.01"), Ok(-1));
        assert_eq!(parse_cents("  7.50  "), Ok(750));
        assert_eq!(parse_cents("-12"), Ok(-1200));
        assert_eq!(parse_cents("0"), Ok(0));
        assert_eq!(parse_cents("00012.30"), Ok(1230));
    }

    #[test]
    fn rejects_invalid_amounts() {
        for bad in [
            "", "+12", "12.", ".5", "1e3", "1E3", "abc", "12.345", "--1", "-", ".",
            "1 2", "１２", "12,34", "12.3.4", "- 1", "0x10", "1_000", "NaN", "inf",
        ] {
            assert!(parse_cents(bad).is_err(), "{bad:?} should be rejected");
        }
    }

    #[test]
    fn handles_full_i64_range_exactly() {
        assert_eq!(parse_cents("92233720368547758.07"), Ok(i64::MAX));
        assert_eq!(parse_cents("-92233720368547758.08"), Ok(i64::MIN));
        assert!(parse_cents("92233720368547758.08").is_err());
        assert!(parse_cents("-92233720368547758.09").is_err());
        assert!(parse_cents("92233720368547759").is_err());
        assert!(parse_cents("99999999999999999999999999999999999999999999").is_err());
        assert_eq!(parse_cents("-0.00"), Ok(0));
    }

    #[test]
    fn formats_full_range() {
        assert_eq!(format_cents(0), "0.00");
        assert_eq!(format_cents(1), "0.01");
        assert_eq!(format_cents(-1), "-0.01");
        assert_eq!(format_cents(-5), "-0.05");
        assert_eq!(format_cents(-100), "-1.00");
        assert_eq!(format_cents(i64::MAX), "92233720368547758.07");
        assert_eq!(format_cents(i64::MIN), "-92233720368547758.08");
    }

    #[test]
    fn round_trips_exactly() {
        for cents in [
            0i64,
            1,
            -1,
            5,
            -5,
            99,
            -99,
            100,
            -100,
            i64::MAX,
            i64::MIN,
            i64::MAX - 1,
            i64::MIN + 1,
            123456789012345,
            -987654321098765,
        ] {
            let text = format_cents(cents);
            assert_eq!(parse_cents(&text), Ok(cents), "round trip failed for {text}");
        }
    }
}
