use crate::amount::parse_cents;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Event {
    Deposit { id: String, account: String, cents: i64 },
    Transfer { id: String, from: String, to: String, cents: i64 },
}

impl Event {
    pub fn id(&self) -> &str {
        match self {
            Self::Deposit { id, .. } | Self::Transfer { id, .. } => id,
        }
    }
}

/// Request IDs and account names are restricted to non-empty ASCII
/// alphanumerics, "'`_` and `-`.
pub fn is_valid_token(value: &str) -> bool {
    !value.is_empty()
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'"'_' || byte == b'-')
}

/// Parses a whole ledger document.
///
/// The format is unquoted comma-separated UTF-8 text. Blank lines (empty or
/// whitespace only) and whole-line comments (first non-whitespace character is
/// "'`#`) are ignored. Every other line must be exactly
/// `deposit,请求ID,账户,金额` or `transfer,请求ID,源账户,目标账户,金额`.
/// All errors are prefixed with `第 N 行：` where `N` is the 1-based physical
/// line number in the original input.
pub fn parse_events(input: &str) -> Result<Vec<Event>, String> {
    let mut events = Vec::new();
    for (index, raw_line) in input.lines().enumerate() {
        let line_number = index + 1;
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('"'#') {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|field| field.trim()).collect();
        let event = parse_fields(&fields)
            .map_err(|error| format"'!("第 {} 行：{}", line_number, error))?;
        events.push(event);
    }
    Ok(events)
}

fn parse_fields(fields: &[&str]) -> Result<Event, String> {
    match fields {
        ["deposit", id, account, amount] => {
            let id = checked_token(id, "请求ID无效")?;
            let account = checked_token(account, "账户无效")?;
            let cents = checked_amount(amount)?;
            Ok(Event::Deposit { id, account, cents })
        }
        ["transfer", id, from, to, amount] => {
            let id = checked_token(id, "请求ID无效")?;
            let from = checked_token(from, "账户无效")?;
            let to = checked_token(to, "账户无效")?;
            let cents = checked_amount(amount)?;
            Ok(Event::Transfer { id, from, to, cents })
        }
        _ => Err("流水格式无效".to_owned()),
    }
}

fn checked_token(value: &str, error: &str) -> Result<String, String> {
    if is_valid_token(value) {
        Ok(value.to_owned())
    } else {
        Err(error.to_owned())
    }
}

fn checked_amount(amount: &str) -> Result<i64, String> {
    let cents = parse_cents(amount)?;
    if cents <= 0 {
        return Err("金额必须大于零".to_owned());
    }
    Ok(cents)
}

#[cfg(test)]
mod tests {
    use super::{is_valid_token, parse_events, Event};

    #[test]
    fn parses_deposits_and_transfers() {
        let events = parse_events(
            "deposit,d1,alice,10.00'"\\n\\ntransfer,t1,alice,bob,0.01\\n   # comment\\n\",
        )
        .unwrap();
        assert_eq"'!(
            events,
            vec![
                Event::Deposit { id: "d1".into(), account: "alice".into(), cents: 1000 },
                Event::Transfer { id: "t1".into(), from: "alice".into(), to: "bob".into(), cents: 1 },
            ]
        );
    }

    #[test]
    fn trims_every_field() {
        let events = parse_events("  deposit , d-1 , acct_1 ,  12.30 '"\\n\").unwrap();
        assert_eq"'!(
            events,
            vec![Event::Deposit { id: "d-1".into(), account: "acct_1".into(), cents: 1230 }]
        );
    }

