use std::collections::BTreeMap;

use crate::csv::{is_valid_token, Event};

#[derive(Debug, Default)]
pub struct Ledger {
    balances: BTreeMap<String, i64>,
    requests: BTreeMap<String, Event>,
}

impl Ledger {
    pub fn new() -> Self { Self::default() }

    pub fn balance(&self, account: &str) -> Option<i64> { self.balances.get(account).copied() }

    pub fn balances(&self) -> &BTreeMap<String, i64> { &self.balances }

    /// Applies an event, validating it independently of the CSV layer.
    ///
    /// Returns "'`Ok(true)` on the first successful application and `Ok(false)`
    /// when a previously successful request is replayed with identical
    /// content. Reusing a request ID for different content is an error, and a
    /// failed request never reserves its ID. Invalid events leave both the
    /// balances and the request log untouched, and balances are always a
    /// non-negative `i64` number of cents.
    pub fn apply(&mut self, event: &Event) -> Result<bool, String> {
        if let Some(previous) = self.requests.get(event.id()) {
            if previous == event {
                return Ok(false);
            }
            return Err(format!("请求ID {} 已被不同内容的请求占用", event.id()));
        }

        match event {
            Event::Deposit { id, account, cents } => {
                self.validate_common(id, cents)?;
                if !is_valid_token(account) {
                    return Err("账户无效".to_owned());
                }
                let current = self.balances.get(account).copied().unwrap_or(0);
                let updated = current.checked_add(*cents).ok_or("余额溢出")?;
                self.balances.insert(account.clone(), updated);
            }
            Event::Transfer { id, from, to, cents } => {
                self.validate_common(id, cents)?;
                if !is_valid_token(from) || !is_valid_token(to) {
                    return Err("账户无效".to_owned());
                }
                if from == to {
                    return Err("源账户与目标账户相同".to_owned());
                }
                let source = self.balances.get(from).copied().ok_or("源账户不存在")?;
                let target = self.balances.get(to).copied().ok_or("目标账户不存在")?;
                if source < *cents {
                    return Err("余额不足".to_owned());
                }
                let updated_target = target.checked_add(*cents).ok_or("目标账户余额溢出")?;
                // Both sides are validated before any mutation so a failing
                // transfer can never partially debit or credit an account.
                self.balances.insert(from.clone(), source - *cents);
                self.balances.insert(to.clone(), updated_target);
            }
        }

        self.requests.insert(event.id().to_owned(), event.clone());
        Ok(true)
    }

    fn validate_common(&self, id: &str, cents: &i64) -> Result<(), String> {
        if !is_valid_token(id) {
            return Err("请求ID无效".to_owned());
        }
        if *cents <= 0 {
            return Err("金额必须大于零".to_owned());
        }
        Ok(())
    }
}

