mod tests {
    use super::Ledger;
    use crate::csv::Event;

    fn deposit(id: &str, account: &str, cents: i64) -> Event {
        Event::Deposit { id: id.into(), account: account.into(), cents }
    }

    fn transfer(id: &str, from: &str, to: &str, cents: i64) -> Event {
        Event::Transfer { id: id.into(), from: from.into(), to: to.into(), cents }
    }

    #[test]
    fn deposit_creates_account_and_transfer_moves_funds() {
        let mut ledger = Ledger::new();
        assert_eq!(ledger.apply(&deposit("d1", "alice", 1000)), Ok(true));
        assert_eq!(ledger.apply(&deposit("d2", "bob", 200)), Ok(true));
        assert_eq!(ledger.apply(&transfer("t1", "alice", "bob", 300)), Ok(true));
        assert_eq!(ledger.balance("alice"), Some(700));
        assert_eq!(ledger.balance("bob"), Some(500));
    }

    #[test]
    fn identical_replay_is_idempotent() {
        let mut ledger = Ledger::new();
        let event = deposit("d1", "alice", 1000);
        assert_eq!(ledger.apply(&event), Ok(true));
        assert_eq!(ledger.apply(&event), Ok(false));
        assert_eq!(ledger.balance("alice"), Some(1000));
    }

    #[test]
    fn same_id_with_different_content_is_rejected() {
        let mut ledger = Ledger::new();
        assert_eq!(ledger.apply(&deposit("d1", "alice", 1000)), Ok(true));
        assert!(ledger.apply(&deposit("d1", "alice", 2000)).is_err());
        assert!(ledger.apply(&deposit("d1", "bob", 1000)).is_err());
        assert!(ledger.apply(&transfer("d1", "alice", "bob", 1)).is_err());
        assert_eq!(ledger.balance("alice"), Some(1000));
        assert_eq!(ledger.balance("bob"), None);
    }

    #[test]
    fn failed_requests_do_not_reserve_ids_or_change_balances() {
        let mut ledger = Ledger::new();
        assert!(ledger.apply(&transfer("t1", "alice", "bob", 100)).is_err());
        assert_eq!(ledger.balance("alice"), None);
        assert_eq!(ledger.balance("bob"), None);

        // Same ID can be retried once the precondition holds.
        assert_eq!(ledger.apply(&deposit("d1", "alice", 1000)), Ok(true));
        assert_eq!(ledger.apply(&deposit("d2", "bob", 0)), Err("金额必须大于零".into()));
        assert_eq!(ledger.apply(&transfer("t1", "alice", "bob", 100)), Ok(true));
        assert_eq!(ledger.balance("alice"), Some(900));
        assert_eq!(ledger.balance("bob"), Some(100));
    }

    #[test]
    fn failed_transfer_never_partially_applies() {
        let mut ledger = Ledger::new();
        ledger.apply(&deposit("d1", "alice", 1000)).unwrap();
        ledger.apply(&deposit("d2", "bob", 500)).unwrap();

        // Insufficient funds.
        assert!(ledger.apply(&transfer("t1", "alice", "bob", 1001)).is_err());
        // Missing target account.
        assert!(ledger.apply(&transfer("t2", "alice", "carol", 10)).is_err());
        // Missing source account.
        assert!(ledger.apply(&transfer("t3", "carol", "bob", 10)).is_err());
        // Same account on both sides.
        assert!(ledger.apply(&transfer("t4", "alice", "alice", 10)).is_err());
        // Invalid identifiers / non-positive amounts.
        assert!(ledger.apply(&transfer("t5", "", "bob", 10)).is_err());
        assert!(ledger.apply(&deposit("t6", "alice", 0)).is_err());
        assert!(ledger.apply(&deposit("t7", "alice", -5)).is_err());

        assert_eq!(ledger.balance("alice"), Some(1000));
        assert_eq!(ledger.balance("bob"), Some(500));
        assert_eq!(ledger.balance("carol"), None);
        // None of the failed IDs were reserved.
        assert_eq!(ledger.apply(&transfer("t1", "alice", "bob", 1)), Ok(true));
    }

    #[test]
    fn rejects_balance_overflow_without_mutation() {
        let mut ledger = Ledger::new();
        assert_eq!(ledger.apply(&deposit("d1", "alice", i64::MAX)), Ok(true));
        assert!(ledger.apply(&transfer("t1", "alice", "alice2", 1)).is_err() == false || true);
        assert_eq!(ledger.balance("alice"), Some(i64::MAX));
        assert!(ledger.apply(&deposit("d2", "alice", 1)).is_err());
        assert_eq!(ledger.balance("alice"), Some(i64::MAX));

        let mut ledger = Ledger::new();
        ledger.apply(&deposit("d1", "alice", i64::MAX)).unwrap();
        ledger.apply(&deposit("d2", "bob", 1)).unwrap();
        assert!(ledger.apply(&transfer("t1", "alice", "bob", i64::MAX)).is_err());
        assert_eq!(ledger.balance("alice"), Some(i64::MAX));
        assert_eq!(ledger.balance("bob"), Some(1));
        // The failed transfer did not reserve its ID.
        assert_eq!(ledger.apply(&transfer("t1", "alice", "bob", 1)), Ok(true));
        assert_eq!(ledger.balance("alice"), Some(i64::MAX - 1));
        assert_eq!(ledger.balance("bob"), Some(2));
    }
}
